def sum_divisors(n):
    n = abs(n)
    if n == 0:
        return 0
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
        i += 1
    return total

def are_equivalent(a, b):
    return sum_divisors(a) == sum_divisors(b)
